184	static int SF32LB_FLASH_RAMFUNC sf32lb_flash_preinit_runtime(void)
185	{
186	  FAR FLASH_HandleTypeDef *hflash;
187	  HAL_StatusTypeDef status;
188	  irqstate_t flags;
189	  uint32_t detected_size;
190	
191	  if (g_flash_hw_initialized)
192	    {
193	      return OK;
194	    }
195	
196	  hflash = &g_spi_nor_flash_ctx.handle;
197	
198	  memset(&g_spi_nor_flash_ctx, 0, sizeof(g_spi_nor_flash_ctx));
199	  memset(&g_spi_nor_flash_dma_handle, 0, sizeof(g_spi_nor_flash_dma_handle));
200	
201	  hflash->Instance = FLASH2;
202	  hflash->base = FLASH2_BASE_ADDR;
203	  hflash->size = SF32LB_NOR_TOTAL_SIZE;
204	  hflash->freq = 24000000;
205	
206	  sf32lb_flash_lock();
207	  flags = up_irq_save();
208	  status = HAL_FLASH_PreInit(hflash);
209	  up_irq_restore(flags);
210	  sf32lb_flash_unlock();
211	
212	  if (status != HAL_OK)
213	    {
214	      syslog(LOG_ERR, "ERROR: NOR runtime preinit failed: %d\n", status);
215	      return -EIO;
216	    }
217	
218	  if (hflash->ctable == NULL)
219	    {
220	      syslog(LOG_ERR, "ERROR: NOR runtime preinit missing command table\n");
221	      return -EIO;
222	    }
223	
224	  /* HAL stores command table in const rodata, which can live in XIP flash.
225	   * During erase/program busy states, repeatedly dereferencing an XIP table
226	   * can break status polling.  Keep a SRAM copy for runtime commands.
227	   */
228	
229	  memcpy(&g_spi_nor_cmd_table_cache, hflash->ctable,
230	         sizeof(g_spi_nor_cmd_table_cache));
231	  hflash->ctable = &g_spi_nor_cmd_table_cache;
232	
233	  /* Exit potential vendor continuous-read state before write/erase. */
234	
235	  HAL_FLASH_ISSUE_CMD(hflash, SPI_FLASH_CMD_RST_EN, 0);
236	  HAL_FLASH_ISSUE_CMD(hflash, SPI_FLASH_CMD_RST, 0);
237	  HAL_Delay_us(30);
238	
239	  /* Board flash2 uses 4-line SPI in normal runtime (line=2 in board init).
240	   * HAL_FLASH_PreInit forces Mode=0; restore quad mode explicitly.
241	   */
242	
243	  hflash->Mode = HAL_FLASH_QMODE;
244	  HAL_FLASH_SET_QUAL_SPI(hflash, true);
245	
246	  /* HAL_FLASH_PreInit sets hflash->dma = NULL but HAL_QSPIEX_WRITE_PAGE
247	   * requires DMA for reliable page-program operations.  Configure DMA
248	   * manually, mirroring what HAL_FLASH_Init would do.
249	   */
250	
251	#ifdef CONFIG_BSP_QSPI2_USING_DMA
252	  hflash->dma = &g_spi_nor_flash_dma_handle;
253	  hflash->dma->Instance                 = FLASH2_DMA_INSTANCE;
254	  hflash->dma->Init.Request             = FLASH2_DMA_REQUEST;
255	  hflash->dma->Init.Direction           = DMA_MEMORY_TO_PERIPH;
256	  hflash->dma->Init.PeriphInc           = DMA_PINC_DISABLE;
257	  hflash->dma->Init.MemInc              = DMA_MINC_ENABLE;
258	  hflash->dma->Init.PeriphDataAlignment = DMA_PDATAALIGN_BYTE;
259	  hflash->dma->Init.MemDataAlignment    = DMA_MDATAALIGN_BYTE;
260	  hflash->dma->Init.Mode                = DMA_NORMAL;
261	  hflash->dma->Init.Priority            = DMA_PRIORITY_MEDIUM;
262	  hflash->dma->Init.BurstSize           = 1;
263	  HAL_FLASH_SET_TXSLOT(hflash, hflash->dma->Init.BurstSize);
264	
265	#else
266	  syslog(LOG_WARNING,
267	         "WARN: CONFIG_BSP_QSPI2_USING_DMA not enabled, NOR writes may fail\n");
268	#endif
269	
270	  /* Ensure NOR is writable -- clear status register protection bits. */
271	
272	  HAL_FLASH_CLR_PROTECT(hflash);
273	  sf32lb_flash_try_global_unlock(hflash);
274	
275	  detected_size = hflash->size;
276	  if (detected_size < SF32LB_NOR_MIN_VALID_SIZE)
277	    {
278	      syslog(LOG_WARNING,
279	             "WARN: NOR detected size too small (%lu), fallback to configured %lu\n",
280	             (unsigned long)detected_size,
281	             (unsigned long)SF32LB_NOR_TOTAL_SIZE);
282	      hflash->size = SF32LB_NOR_TOTAL_SIZE;
283	    }
284	
285	  g_flash_hw_initialized = true;
286	
287	  return OK;
288	}
