290	static int sf32lb_nor_sync_geometry(FAR struct sf32lb_nor_dev_s *priv,
291	                                    bool allow_offset_fallback)
292	{
293	  uint32_t flash_size;
294	  uint32_t offset_bytes;
295	  uint32_t fallback_bytes;
296	  uint32_t max_blocks;
297	  uint32_t region_size;
298	
299	  if (priv == NULL || priv->spi_flash_handle == NULL)
300	    {
301	      return -EINVAL;
302	    }
303	
304	  flash_size = priv->spi_flash_handle->size;
305	  if (flash_size < SF32LB_NOR_PAGE_SIZE)
306	    {
307	      syslog(LOG_ERR, "ERROR: NOR flash size invalid: %lu\n",
308	             (unsigned long)flash_size);
309	      return -ENOSPC;
310	    }
311	
312	  offset_bytes = priv->offset * SF32LB_NOR_PAGE_SIZE;
313	  if (offset_bytes >= flash_size)
314	    {
315	      if (!allow_offset_fallback)
316	        {
317	          syslog(LOG_ERR,
318	                 "ERROR: NOR partition offset out of range: off=%lu size=%lu\n",
319	                 (unsigned long)offset_bytes,
320	                 (unsigned long)flash_size);
321	          return -ENOSPC;
322	        }
323	
324	      /* If configured offset doesn't fit detected flash size, fallback to
325	       * half-flash split to keep app image and fs separated in most layouts.
326	       */
327	
328	      fallback_bytes = (flash_size / 2U) & ~(SF32LB_NOR_PAGE_SIZE - 1U);
329	      if (fallback_bytes >= flash_size)
330	        {
331	          fallback_bytes = 0;
332	        }
333	
334	      syslog(LOG_WARNING,
335	             "WARN: NOR offset %lu invalid for flash size %lu, fallback to %lu\n",
336	             (unsigned long)offset_bytes,
337	             (unsigned long)flash_size,
338	             (unsigned long)fallback_bytes);
339	
340	      priv->offset = fallback_bytes / SF32LB_NOR_PAGE_SIZE;
341	      offset_bytes = fallback_bytes;
342	    }
343	
344	  region_size = (flash_size - offset_bytes) & ~(SF32LB_NOR_PAGE_SIZE - 1U);
345	  priv->nsectors = region_size / SF32LB_NOR_PAGE_SIZE;
346	
347	  max_blocks = priv->limit_blocks;
348	  if (max_blocks > 0 && priv->nsectors > max_blocks)
349	    {
350	      priv->nsectors = max_blocks;
351	    }
352	
353	  priv->mem_base = priv->spi_flash_handle->base + offset_bytes;
354	
355	  if (priv->nsectors == 0)
356	    {
357	      syslog(LOG_ERR,
358	             "ERROR: NOR partition has no usable sectors: off=%lu size=%lu\n",
359	             (unsigned long)offset_bytes,
360	             (unsigned long)flash_size);
361	      return -ENOSPC;
362	    }
363	
364	  return OK;
365	}
