367	static bool sf32lb_flash_verify_erased(uint32_t addr, uint32_t size)
368	{
369	  uint8_t checkbuf[32];
370	  uint32_t check_len;
371	  uint32_t flash_off;
372	  FAR FLASH_HandleTypeDef *hflash;
373	  uint32_t i;
374	
375	  if (size == 0)
376	    {
377	      return true;
378	    }
379	
380	  hflash = &g_spi_nor_flash_ctx.handle;
381	  if (hflash == NULL || addr < hflash->base)
382	    {
383	      return false;
384	    }
385	
386	  flash_off = addr - hflash->base;
387	  check_len = size > sizeof(checkbuf) ? sizeof(checkbuf) : size;
388	
389	  if (sf32lb_flash_raw_read_bytes(hflash, flash_off, checkbuf, check_len) < 0)
390	    {
391	      return false;
392	    }
393	
394	  for (i = 0; i < check_len; i++)
395	    {
396	      if (checkbuf[i] != 0xFF)
397	        {
398	          return false;
399	        }
400	    }
401	
402	  if (size > check_len)
403	    {
404	      flash_off = (addr + size - check_len) - hflash->base;
405	      if (sf32lb_flash_raw_read_bytes(hflash, flash_off, checkbuf,
406	                                      check_len) < 0)
407	        {
408	          return false;
409	        }
410	
411	      for (i = 0; i < check_len; i++)
412	        {
413	          if (checkbuf[i] != 0xFF)
414	            {
415	              return false;
416	            }
417	        }
418	    }
419	
420	  return true;
421	}
422	
423	static bool sf32lb_flash_verify_written(uint32_t addr,
424	                                        FAR const uint8_t *buffer,
425	                                        uint32_t size)
426	{
427	  uint8_t checkbuf[32];
428	  FAR FLASH_HandleTypeDef *hflash;
429	  uint32_t flash_off;
430	  uint32_t check_len;
431	
432	  if (buffer == NULL || size == 0)
433	    {
434	      return false;
435	    }
436	
437	  hflash = &g_spi_nor_flash_ctx.handle;
438	  if (hflash == NULL || addr < hflash->base)
439	    {
440	      return false;
441	    }
442	
443	  check_len = size > 32U ? 32U : size;
444	  flash_off = addr - hflash->base;
445	
446	  if (sf32lb_flash_raw_read_bytes(hflash, flash_off, checkbuf, check_len) < 0)
447	    {
448	      return false;
449	    }
450	
451	  if (memcmp(checkbuf, buffer, check_len) != 0)
452	    {
453	      syslog(LOG_ERR,
454	             "ERROR: verify mismatch at 0x%08lx: "
455	             "flash=%02x%02x%02x%02x%02x%02x%02x%02x "
456	             "expect=%02x%02x%02x%02x%02x%02x%02x%02x\n",
457	             (unsigned long)addr,
458	                  checkbuf[0], checkbuf[1], checkbuf[2], checkbuf[3],
459	                  checkbuf[4], checkbuf[5], checkbuf[6], checkbuf[7],
460	             buffer[0], buffer[1], buffer[2], buffer[3],
461	             buffer[4], buffer[5], buffer[6], buffer[7]);
462	      return false;
463	    }
464	
465	  return true;
466	}
