527	static int SF32LB_FLASH_RAMFUNC
528	sf32lb_flash_raw_read_bytes(FAR FLASH_HandleTypeDef *hflash,
529	                            uint32_t offset,
530	                            FAR uint8_t *out,
531	                            uint32_t len)
532	{
533	  irqstate_t flags;
534	  uint32_t word;
535	  uint32_t i;
536	
537	  if (hflash == NULL || out == NULL || len == 0 || len > 32)
538	    {
539	      return -EINVAL;
540	    }
541	
542	  sf32lb_flash_lock();
543	  flags = up_irq_save();
544	
545	  HAL_FLASH_MANUAL_CMD(hflash, 0, 1, 0, 0, 0, 2, 1, 1);
546	  HAL_FLASH_WRITE_DLEN(hflash, len);
547	  if (HAL_FLASH_SET_CMD(hflash, 0x03, offset) != HAL_OK)
548	    {
549	      up_irq_restore(flags);
550	      sf32lb_flash_unlock();
551	      return -EIO;
552	    }
553	
554	  for (i = 0; i < len; i += 4)
555	    {
556	      word = HAL_FLASH_READ32(hflash);
557	      out[i + 0] = (uint8_t)(word & 0xFF);
558	      if ((i + 1) < len)
559	        {
560	          out[i + 1] = (uint8_t)((word >> 8) & 0xFF);
561	        }
562	
563	      if ((i + 2) < len)
564	        {
565	          out[i + 2] = (uint8_t)((word >> 16) & 0xFF);
566	        }
567	
568	      if ((i + 3) < len)
569	        {
570	          out[i + 3] = (uint8_t)((word >> 24) & 0xFF);
571	        }
572	    }
573	
574	  up_irq_restore(flags);
575	  sf32lb_flash_unlock();
576	  return OK;
577	}
