579	static ssize_t SF32LB_FLASH_RAMFUNC
580	sf32lb_flash_raw_read_range(FAR FLASH_HandleTypeDef *hflash,
581	                            uint32_t addr,
582	                            FAR uint8_t *out,
583	                            uint32_t len)
584	{
585	  uint32_t offset;
586	  uint32_t done;
587	  uint32_t chunk;
588	  int ret;
589	
590	  if (hflash == NULL || out == NULL)
591	    {
592	      return -EINVAL;
593	    }
594	
595	  if (len == 0)
596	    {
597	      return 0;
598	    }
599	
600	  offset = addr >= hflash->base ? (addr - hflash->base) : addr;
601	  done = 0;
602	  while (done < len)
603	    {
604	      chunk = len - done;
605	      if (chunk > 32)
606	        {
607	          chunk = 32;
608	        }
609	
610	      ret = sf32lb_flash_raw_read_bytes(hflash, offset + done,
611	                                        out + done, chunk);
612	      if (ret < 0)
613	        {
614	          return ret;
615	        }
616	
617	      done += chunk;
618	    }
619	
620	  return (ssize_t)done;
621	}
