623	static bool sf32lb_flash_is_xip_buffer(FAR const uint8_t *buffer,
624	                                       uint32_t size)
625	{
626	  uintptr_t start;
627	  uintptr_t end;
628	  uintptr_t xip_start;
629	  uintptr_t xip_end;
630	
631	  if (buffer == NULL || size == 0)
632	    {
633	      return false;
634	    }
635	
636	  start = (uintptr_t)buffer;
637	  end = start + (uintptr_t)size;
638	  xip_start = (uintptr_t)FLASH2_BASE_ADDR;
639	  xip_end = xip_start + (uintptr_t)SF32LB_NOR_TOTAL_SIZE;
640	
641	  if (end < start)
642	    {
643	      return false;
644	    }
645	
646	  return (start < xip_end) && (end > xip_start);
647	}
