649	static int sf32lb_nor_prepare_io(FAR struct sf32lb_nor_dev_s *priv,
650	                                 uint32_t offset, uint32_t nbytes)
651	{
652	  uint64_t part_size;
653	  int ret;
654	
655	  if (priv == NULL || priv->spi_flash_handle == NULL)
656	    {
657	      return -EINVAL;
658	    }
659	
660	  if (!g_flash_hw_initialized)
661	    {
662	      ret = sf32lb_flash_preinit_runtime();
663	      if (ret < 0)
664	        {
665	          return ret;
666	        }
667	    }
668	
669	  ret = sf32lb_nor_sync_geometry(priv, true);
670	  if (ret < 0)
671	    {
672	      return ret;
673	    }
674	
675	  part_size = (uint64_t)priv->nsectors * SF32LB_NOR_PAGE_SIZE;
676	  if (((uint64_t)offset + (uint64_t)nbytes) > part_size)
677	    {
678	      syslog(LOG_ERR,
679	             "ERROR: NOR io out of range: off=%lu nbytes=%lu part=%lu\n",
680	             (unsigned long)offset,
681	             (unsigned long)nbytes,
682	             (unsigned long)part_size);
683	      return -ENOSPC;
684	    }
685	
686	  return OK;
687	}
