689	static int SF32LB_FLASH_RAMFUNC sf32lb_nor_erase_range(FAR FLASH_HandleTypeDef *hflash,
690	                                                       uint32_t addr, uint32_t size)
691	{
692	  uint32_t erase_addr;
693	  uint32_t erase_size;
694	  uint32_t chunk_addr;
695	  uint32_t chunk_size;
696	  uint32_t phys_addr;
697	  int ret = OK;
698	  irqstate_t flags;
699	
700	  if (hflash == NULL)
701	    {
702	      return -EINVAL;
703	    }
704	
705	  if (!g_flash_hw_initialized)
706	    {
707	      ret = sf32lb_flash_preinit_runtime();
708	      if (ret < 0)
709	        {
710	          return ret;
711	        }
712	    }
713	
714	  if (size == 0)
715	    {
716	      return OK;
717	    }
718	
719	  if (size >= hflash->size)
720	    {
721	      sf32lb_flash_lock();
722	      flags = up_irq_save();
723	      ret = HAL_QSPIEX_CHIP_ERASE(hflash);
724	      up_irq_restore(flags);
725	      sf32lb_flash_unlock();
726	      return ret == 0 ? OK : -EIO;
727	    }
728	
729	  if (addr >= hflash->base)
730	    {
731	      addr -= hflash->base;
732	    }
733	
734	  if (!IS_ALIGNED(QSPI_NOR_SECT_SIZE, addr) ||
735	      !IS_ALIGNED(QSPI_NOR_SECT_SIZE, size))
736	    {
737	      return -EINVAL;
738	    }
739	
740	  erase_addr = GET_ALIGNED_DOWN(QSPI_NOR_SECT_SIZE, addr);
741	  erase_size = GET_ALIGNED_UP(QSPI_NOR_SECT_SIZE, size);
742	
743	  while (erase_size > 0)
744	    {
745	      chunk_addr = erase_addr;
746	      chunk_size = 0;
747	      sf32lb_flash_lock();
748	      flags = up_irq_save();
749	      if (IS_ALIGNED(QSPI_NOR_BLK64_SIZE, erase_addr) &&
750	          erase_size >= QSPI_NOR_BLK64_SIZE)
751	        {
752	          chunk_size = QSPI_NOR_BLK64_SIZE;
753	          if (hflash->size > NOR_FLASH_MAX_3B_SIZE)
754	            {
755	              ret = HAL_FLASH_PRE_CMD(hflash, SPI_FLASH_CMD_BE4BA);
756	            }
757	          else
758	            {
759	              ret = HAL_FLASH_PRE_CMD(hflash, SPI_FLASH_CMD_BE64);
760	            }
761	
762	          if (ret != 0)
763	            {
764	              up_irq_restore(flags);
765	              sf32lb_flash_unlock();
766	              syslog(LOG_ERR,
767	                     "ERROR: NOR erase precmd failed: addr=0x%08lx cmd=BE ret=%d\n",
768	                     (unsigned long)erase_addr,
769	                     ret);
770	              return -EIO;
771	            }
772	
773	          ret = HAL_QSPIEX_BLK64_ERASE(hflash, erase_addr);
774	          if (ret == 0)
775	            {
776	              erase_addr += QSPI_NOR_BLK64_SIZE;
777	              erase_size -= QSPI_NOR_BLK64_SIZE;
778	            }
779	        }
780	      else
781	        {
782	          chunk_size = QSPI_NOR_SECT_SIZE;
783	          if (hflash->size > NOR_FLASH_MAX_3B_SIZE)
784	            {
785	              ret = HAL_FLASH_PRE_CMD(hflash, SPI_FLASH_CMD_SE4BA);
786	            }
787	          else
788	            {
789	              ret = HAL_FLASH_PRE_CMD(hflash, SPI_FLASH_CMD_SE);
790	            }
791	
792	          if (ret != 0)
793	            {
794	              up_irq_restore(flags);
795	              sf32lb_flash_unlock();
796	              syslog(LOG_ERR,
797	                     "ERROR: NOR erase precmd failed: addr=0x%08lx cmd=SE ret=%d\n",
798	                     (unsigned long)erase_addr,
799	                     ret);
800	              return -EIO;
801	            }
802	
803	          ret = HAL_QSPIEX_SECT_ERASE(hflash, erase_addr);
804	          if (ret == 0)
805	            {
806	              erase_addr += QSPI_NOR_SECT_SIZE;
807	              erase_size -= QSPI_NOR_SECT_SIZE;
808	            }
809	        }
810	      up_irq_restore(flags);
811	      sf32lb_flash_unlock();
812	
813	      if (ret != 0)
814	        {
815	          syslog(LOG_ERR,
816	                 "ERROR: NOR erase failed: addr=0x%08lx remaining=0x%08lx ret=%d\n",
817	                 (unsigned long)erase_addr,
818	                 (unsigned long)erase_size,
819	                 ret);
820	          return -EIO;
821	        }
822	
823	      phys_addr = hflash->base + chunk_addr;
824	      sf32lb_flash_restore_ahb_read(hflash);
825	      sf32lb_flash_cache_invalidate(phys_addr, chunk_size);
826	      if (!sf32lb_flash_verify_erased(phys_addr, chunk_size))
827	        {
828	          syslog(LOG_ERR,
829	                 "ERROR: NOR erase verify failed: addr=0x%08lx size=0x%08lx\n",
830	                 (unsigned long)phys_addr,
831	                 (unsigned long)chunk_size);
832	          return -EIO;
833	        }
834	    }
835	
836	  return OK;
837	}
838	
839	static ssize_t SF32LB_FLASH_RAMFUNC sf32lb_nor_write_range(FAR FLASH_HandleTypeDef *hflash,
840	                                                           uint32_t addr,
841	                                                           FAR const uint8_t *buffer,
842	                                                           uint32_t size)
843	{
844	  uint32_t taddr;
845	  uint32_t tsize;
846	  uint32_t aligned_size;
847	  uint32_t start;
848	  uint32_t chunk_addr;
849	  uint32_t chunk_size;
850	  uint32_t phys_addr;
851	  ssize_t cnt;
852	  int ret;
853	  FAR const uint8_t *tbuf;
854	  FAR const uint8_t *chunk_buf;
855	  uint8_t stage_buf[QSPI_NOR_PAGE_SIZE];
856	
857	  if (hflash == NULL || buffer == NULL || size == 0)
858	    {
859	      return -EINVAL;
860	    }
861	
862	  if (!g_flash_hw_initialized)
863	    {
864	      if (sf32lb_flash_preinit_runtime() < 0)
865	        {
866	          return -EIO;
867	        }
868	    }
869	
870	  cnt = 0;
871	  tsize = size;
872	  tbuf = buffer;
873	
874	  if (addr >= hflash->base)
875	    {
876	      taddr = addr - hflash->base;
877	    }
878	  else
879	    {
880	      taddr = addr;
881	    }
882	
883	  aligned_size = QSPI_NOR_PAGE_SIZE;
884	  start = taddr & (aligned_size - 1);
885	
886	  if (start > 0)
887	    {
888	      start = aligned_size - start;
889	      if (start > tsize)
890	        {
891	          start = tsize;
892	        }
893	
894	      chunk_addr = taddr;
895	      chunk_size = start;
896	      chunk_buf = tbuf;
897	
898	      if (sf32lb_flash_is_xip_buffer(chunk_buf, chunk_size))
899	        {
900	          memcpy(stage_buf, chunk_buf, chunk_size);
901	          chunk_buf = stage_buf;
902	        }
903	
904	      sf32lb_flash_lock();
905	      ret = HAL_QSPIEX_WRITE_PAGE(hflash, taddr, chunk_buf, start);
906	      sf32lb_flash_unlock();
907	      if (ret != (int)start)
908	        {
909	          syslog(LOG_ERR,
910	                 "ERROR: NOR write unaligned head failed: addr=0x%08lx size=%lu ret=%d\n",
911	                 (unsigned long)taddr,
912	                 (unsigned long)start,
913	                 ret);
914	          return -EIO;
915	        }
916	
917	      phys_addr = hflash->base + chunk_addr;
918	      sf32lb_flash_restore_ahb_read(hflash);
919	      sf32lb_flash_cache_invalidate(phys_addr, chunk_size);
920	      if (!sf32lb_flash_verify_written(phys_addr, chunk_buf, chunk_size))
921	        {
922	          syslog(LOG_ERR,
923	                 "ERROR: NOR write verify failed: addr=0x%08lx size=%lu\n",
924	                 (unsigned long)phys_addr,
925	                 (unsigned long)chunk_size);
926	          return -EIO;
927	        }
928	
929	      taddr += start;
930	      tbuf += start;
931	      tsize -= start;
932	      cnt += start;
933	    }
934	
935	  while (tsize >= aligned_size)
936	    {
937	      chunk_addr = taddr;
938	      chunk_size = aligned_size;
939	      chunk_buf = tbuf;
940	
941	      if (sf32lb_flash_is_xip_buffer(chunk_buf, chunk_size))
942	        {
943	          memcpy(stage_buf, chunk_buf, chunk_size);
944	          chunk_buf = stage_buf;
945	        }
946	
947	      sf32lb_flash_lock();
948	      ret = HAL_QSPIEX_WRITE_PAGE(hflash, taddr, chunk_buf, aligned_size);
949	      sf32lb_flash_unlock();
950	      if (ret != (int)aligned_size)
951	        {
952	          syslog(LOG_ERR,
953	                 "ERROR: NOR write page failed: addr=0x%08lx size=%lu ret=%d\n",
954	                 (unsigned long)taddr,
955	                 (unsigned long)aligned_size,
956	                 ret);
957	          return -EIO;
958	        }
959	
960	      phys_addr = hflash->base + chunk_addr;
961	      sf32lb_flash_restore_ahb_read(hflash);
962	      sf32lb_flash_cache_invalidate(phys_addr, chunk_size);
963	      if (!sf32lb_flash_verify_written(phys_addr, chunk_buf, chunk_size))
964	        {
965	          syslog(LOG_ERR,
966	                 "ERROR: NOR write verify failed: addr=0x%08lx size=%lu\n",
967	                 (unsigned long)phys_addr,
968	                 (unsigned long)chunk_size);
969	          return -EIO;
970	        }
971	
972	      taddr += aligned_size;
973	      tbuf += aligned_size;
974	      tsize -= aligned_size;
975	      cnt += aligned_size;
976	    }
977	
978	  if (tsize > 0)
979	    {
980	      chunk_addr = taddr;
981	      chunk_size = tsize;
982	      chunk_buf = tbuf;
983	
984	      if (sf32lb_flash_is_xip_buffer(chunk_buf, chunk_size))
985	        {
986	          memcpy(stage_buf, chunk_buf, chunk_size);
987	          chunk_buf = stage_buf;
988	        }
989	
990	      sf32lb_flash_lock();
991	      ret = HAL_QSPIEX_WRITE_PAGE(hflash, taddr, chunk_buf, tsize);
992	      sf32lb_flash_unlock();
993	      if (ret != (int)tsize)
994	        {
995	          syslog(LOG_ERR,
996	                 "ERROR: NOR write tail failed: addr=0x%08lx size=%lu ret=%d\n",
997	                 (unsigned long)taddr,
998	                 (unsigned long)tsize,
999	                 ret);
1000	          return -EIO;
1001	        }
1002	
1003	      phys_addr = hflash->base + chunk_addr;
1004	      sf32lb_flash_restore_ahb_read(hflash);
1005	      sf32lb_flash_cache_invalidate(phys_addr, chunk_size);
1006	      if (!sf32lb_flash_verify_written(phys_addr, chunk_buf, chunk_size))
1007	        {
1008	          syslog(LOG_ERR,
1009	                 "ERROR: NOR write verify failed: addr=0x%08lx size=%lu\n",
1010	                 (unsigned long)phys_addr,
1011	                 (unsigned long)chunk_size);
1012	          return -EIO;
1013	        }
1014	
1015	      cnt += tsize;
1016	    }
1017	
1018	  return cnt;
1019	}
