1025	static ssize_t sf32lb_nor_read(FAR struct mtd_dev_s *dev, off_t offset,
1026	                               size_t nbytes, FAR uint8_t *buffer)
1027	{
1028	  FAR struct sf32lb_nor_dev_s *priv = (FAR struct sf32lb_nor_dev_s *)dev;
1029	  int ret;
1030	
1031	  if (offset < 0)
1032	    {
1033	      return -EINVAL;
1034	    }
1035	
1036	  ret = sf32lb_nor_prepare_io(priv, (uint32_t)offset, (uint32_t)nbytes);
1037	  if (ret < 0)
1038	    {
1039	      return ret;
1040	    }
1041	
1042	  ret = sf32lb_flash_raw_read_range(priv->spi_flash_handle,
1043	                                    priv->mem_base + offset,
1044	                                    buffer,
1045	                                    (uint32_t)nbytes);
1046	  if (ret < 0)
1047	    {
1048	      return ret;
1049	    }
1050	
1051	  return (ssize_t)nbytes;
1052	}
1053	
1054	static ssize_t sf32lb_nor_write(FAR struct mtd_dev_s *dev, off_t offset,
1055	                                size_t nbytes, FAR const uint8_t *buffer)
1056	{
1057	  FAR struct sf32lb_nor_dev_s *priv = (FAR struct sf32lb_nor_dev_s *)dev;
1058	  uint32_t addr = priv->mem_base + offset;
1059	  ssize_t written;
1060	  int ret;
1061	
1062	  if (offset < 0)
1063	    {
1064	      return -EINVAL;
1065	    }
1066	
1067	  ret = sf32lb_nor_prepare_io(priv, (uint32_t)offset, (uint32_t)nbytes);
1068	  if (ret < 0)
1069	    {
1070	      return ret;
1071	    }
1072	
1073	  written = sf32lb_nor_write_range(priv->spi_flash_handle, addr, buffer,
1074	                                   (uint32_t)nbytes);
1075	  if (written < 0)
1076	    {
1077	      return written;
1078	    }
1079	
1080	  sf32lb_flash_cache_invalidate(addr, (uint32_t)nbytes);
1081	  return written;
1082	}
