void BSP_SetFlash2DIV(uint16_t div) { mpi2_div = div; }
void BSP_SetFlash3DIV(uint16_t div) { mpi3_div = div; }
void BSP_SetFlash4DIV(uint16_t div) { mpi4_div = div; }
void BSP_SetFlash5DIV(uint16_t div) { mpi5_div = div; }

static uint32_t otp_flash_addr = 0x10000000;  /* AUTO_FLASH_MAC_ADDRESS */

uint32_t BSP_GetOtpBase(void)
{
  return otp_flash_addr;
}

/****************************************************************************
 * Name: BSP_Board_PreInit
 *
 * Description:
 *   Minimal board pre-init for bootloader.
 *   Sets up HXT48, DLL1 (CPU), DLL2 (PSRAM clocks).
 *   Called by HAL_PreInit() in sf32lb58_allocateheap.c.
 *
 ****************************************************************************/

void BSP_Board_PreInit(void)
{
#ifdef SOC_BF0_HCPU
  /* Enable 48MHz crystal and select as system clock source */

  HAL_HPAON_EnableXT48();
  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_HP_PERI, RCC_CLK_PERI_HXT48);

  if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
    {
      /* Halt LCPU */

      HAL_HPAON_WakeCore(CORE_ID_LCPU);
      HAL_RCC_Reset_and_Halt_LCPU(1);

      /* Enable DLL */

      HAL_PMU_EnableDLL(1);
      HAL_PMU_SWITCH_VRET_LOWER();
      HAL_HPAON_StartGTimer();

      /* LCPU clocks */

      HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_LP_PERI, RCC_CLK_PERI_HXT48);
      HAL_LPAON_EnableXT48();
      HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
      HAL_RCC_LCPU_SetDiv(1, 1, 3);
    }

  /* Enable bandgap */

  __HAL_SYSCFG_HPBG_EN();
  __HAL_SYSCFG_HPBG_VDDPSW_EN();

  /* DLL1 at 240MHz for CPU */

  HAL_RCC_HCPU_EnableDLL1(240000000);
  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_DLL1);

  /* Reset HAL_Delay_us calibration */

  HAL_Delay_us(0);

  /* Set flash dividers */

  mpi1_div = 1;
  mpi2_div = 1;
  mpi3_div = 3;
  mpi4_div = 3;
  mpi5_div = 3;

#ifdef BSP_USING_PSRAM
  /* Configure DLL2 at 288MHz for PSRAM controller */

  HAL_RCC_HCPU_EnableDLL2(288000000);

  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH2, RCC_CLK_FLASH_DLL2);

  MODIFY_REG(hwp_hpsys_cfg->USBR, HPSYS_CFG_USBR_FREQCTRL_Msk,
             MAKE_REG_VAL(96, HPSYS_CFG_USBR_FREQCTRL_Msk,
                          HPSYS_CFG_USBR_FREQCTRL_Pos));
#endif

  /* Set MPI1 divider if using high-speed mode */

#ifdef BSP_ENABLE_MPI1
#ifdef BSP_MPI1_MODE_4
  mpi1_div = HAL_RCC_GetHCLKFreq() / 60000000;
  if (mpi1_div < 1)
    {
      mpi1_div = 1;
    }

  HAL_RCC_HCPU_SetDiv(RCC_CLK_MOD_FLASH1, mpi1_div - 1);
  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
#endif
#endif

#ifdef HAL_MPI_MODULE_ENABLED
  HAL_MPI_CfgFlash(1);
#endif
#ifdef BSP_USING_PSRAM
  HAL_MPI_CfgPsram(1);
#endif
#endif /* SOC_BF0_HCPU */
}

