330	static int read_nand(uint32_t addr, const int8_t *buf, uint32_t size)
331	{
332	    int cnt;
333	    uint32_t fill, offset;
334	
335	    cnt = 0;
336	    offset = addr >= spi_nand_handle.handle.base
337	             ? addr - spi_nand_handle.handle.base
338	             : addr;
339	    while (size > 0)
340	    {
341	        fill = size > nand_pagesize ? nand_pagesize : size;
342	        if (bbm_read_page(offset / nand_blksize,
343	                          (offset / nand_pagesize) &
344	                          (nand_blksize / nand_pagesize - 1),
345	                          offset & (nand_pagesize - 1), (uint8_t *)(buf + cnt),
346	                          fill, NULL, 0) != fill)
347	            break;
348	        cnt += fill;
349	        size -= fill;
350	        offset += fill;
351	    }
352	    return cnt;
353	}
