384	// Return:
385	// BOOT_INVALID_ADDR means init failed
386	// 1 means init success,
387	
388	static int boot_flash_init(boot_flash_t flash)
389	{
390	    int ret = -1;
391	    int flash_en;
392	    flash_read_func flash_reader = NULL;
393	    uint32_t flash_addr = boot_get_flash_start_addr(flash);
394	    // Only need check flash1 and flash2
395	    if (flash_addr == BOOT_INVALID_ADDR)
396	        return ret;
397	    uint8_t id = flash == BOOT_FLASH1 ? 0 : 1;
398	    flash_enable_func init_func;
399	
400	    /* init mpi5 for OTA */
401	    init_mpi5();
402	
403	    if (flash == BOOT_FLASH1)
404	    {
405	        init_func = BSP_Flash_hw1_init;
406	        flash_reader = read_nor;
407	    }
408	    else if (flash == BOOT_FLASH3)
409	    {
410	#if defined(BSP_ENABLE_MPI3)
411	#if defined(BSP_USING_NOR_FLASH3)
412	        init_func = BSP_Flash_hw3_init;
413	        flash_reader = read_nor;
414	#else
415	        init_func = boot_nand_init;
416	        flash_reader = read_nand;
417	#endif /* BSP_USING_NOR_FLASH3 */
418	#endif     /* BSP_ENABLE_MPI3 */
419	    }
420	    else if (flash == BOOT_FLASH4)
421	    {
422	#if defined(BSP_ENABLE_MPI4)
423	#if defined(BSP_USING_NOR_FLASH4)
424	        init_func = BSP_Flash_hw4_init;
425	        flash_reader = read_nor;
426	#else
427	        init_func = boot_nand_init;
428	        flash_reader = read_nand;
429	#endif /* BSP_USING_NOR_FLASH4 */
430	#endif     /* BSP_ENABLE_MPI4 */
431	    }
432	    else
433	    {
434	        HAL_ASSERT(0);
435	    }
436	
437	    // Enable flash with single mode
438	    // flash_set_dual_mode(id, 0);
439	    flash_en = init_func();
440	
441	    // Enable failed
442	    if (!flash_en)
443	    {
444	        return ret;
445	    }
446	    else
447	    {
448	        ret = 1; // flash existed
449	    }
450	
451	    boot_set_flash_read_func(flash_reader);
452	    dfu_flash_reader = flash_reader;
453	
454	    return ret;
455	}
