611	static void update_sec_flash(struct sec_configuration *sec_config)
612	{
613	    uint32_t flash_addr = FLASH_BASE_ADDR;
614	    //uint32_t size = (sizeof(struct sec_configuration) + SPI_NAND_PAGE_SIZE * 2) & (~(SPI_NAND_PAGE_SIZE * 2 - 1));
615	    uint32_t size = sizeof(struct sec_configuration);
616	    if (size % 4096 != 0)
617	    {
618	        size = (size + 4096) / 4096 * 4096;
619	    }
620	    mpi5_flash_eraser(flash_addr, size);
621	    mpi5_flash_writer(flash_addr, (const int8_t *)sec_config, sizeof(struct sec_configuration));
622	
623	    SCB_InvalidateDCache_by_Addr((void *)flash_addr, size);
624	    SCB_InvalidateICache_by_Addr((void *)flash_addr, size);
625	    g_sec_config = (struct sec_configuration *)FLASH_BASE_ADDR;
626	}
