628	static void select_boot()
629	{
630	    uint8_t hcpu_des = HAL_Get_backup(RTC_BACKUP_NAND_OTA_DES);
631	    uint32_t hcpu_len = HAL_Get_backup(RTC_BAKCUP_OTA_FORCE_MODE);
632	    temp_sec_config = &g_temp_sec_config;
633	
634	    struct sec_configuration *flash_config = (struct sec_configuration *)FLASH_BASE_ADDR;
635	    //memcpy((const int8_t *)temp_sec_config, (uint8_t *)MPI5_MEM_BASE, sizeof(struct sec_configuration));
636	    read_nor(FLASH_BASE_ADDR, (const int8_t *)temp_sec_config, sizeof(struct sec_configuration));
637	
638	    int hcpu1_img_idx = DFU_FLASH_IMG_IDX(DFU_FLASH_IMG_HCPU);
639	    int hcpu2_img_idx = DFU_FLASH_IMG_IDX(DFU_FLASH_IMG_HCPU2);
640	    // HAL_sw_breakpoint();
641	
642	    if (sec_config_cache.running_imgs[CORE_HCPU] == &(flash_config->imgs[hcpu1_img_idx]))
643	    {
644	        // now we are running on hcpu1
645	        switch (hcpu_des)
646	        {
647	        case DFU_DES_RUNNING_ON_HCPU1:
648	        {
649	            // normal power on hcpu1
650	            break;
651	        }
652	        case DFU_DES_SWITCH_TO_HCPU2:
653	        {
654	            // switch to hcpu2
655	
656	            sec_config_cache.running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu2_img_idx]);
657	
658	            hcpu_des = DFU_DES_UPDATE_HCPU2;
659	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
660	
661	            temp_sec_config->running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu2_img_idx]);
662	            if (hcpu_len != 0)
663	            {
664	                temp_sec_config->imgs[DFU_FLASH_IMG_IDX(DFU_FLASH_IMG_HCPU2)].length = hcpu_len;
665	            }
666	
667	            update_sec_flash(temp_sec_config);
668	            break;
669	        }
670	        case DFU_DES_UPDATE_HCPU2:
671	        {
672	            // switch to hcpu2 fail, back to hcpu1
673	            sec_config_cache.running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu1_img_idx]);
674	            hcpu_des = DFU_DES_RUNNING_ON_HCPU1;
675	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
676	
677	            temp_sec_config->running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu1_img_idx]);
678	            update_sec_flash(temp_sec_config);
679	            break;
680	        }
681	        case DFU_DES_NONE:
682	        {
683	            // first power on, use current
684	            hcpu_des = DFU_DES_RUNNING_ON_HCPU1;
685	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
686	            break;
687	        }
688	        default:
689	            hcpu_des = DFU_DES_RUNNING_ON_HCPU1;
690	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
691	        }
692	    }
693	    else if (sec_config_cache.running_imgs[CORE_HCPU] == &(flash_config->imgs[hcpu2_img_idx]))
694	    {
695	        // now we are running on hcpu2
696	        switch (hcpu_des)
697	        {
698	        case DFU_DES_RUNNING_ON_HCPU2:
699	        {
700	            // normal power on hcpu2
701	            break;
702	        }
703	        case DFU_DES_SWITCH_TO_HCPU1:
704	        {
705	            // switch to hcpu1
706	            sec_config_cache.running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu1_img_idx]);
707	            hcpu_des = DFU_DES_UPDATE_HCPU1;
708	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
709	
710	            temp_sec_config->running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu1_img_idx]);
711	            if (hcpu_len != 0)
712	            {
713	                temp_sec_config->imgs[DFU_FLASH_IMG_IDX(DFU_FLASH_IMG_HCPU)].length = hcpu_len;
714	            }
715	
716	            update_sec_flash(temp_sec_config);
717	            break;
718	        }
719	        case DFU_DES_UPDATE_HCPU1:
720	        {
721	            // switch to hcpu1 fail, back to hcpu2
722	            sec_config_cache.running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu2_img_idx]);
723	            hcpu_des = DFU_DES_RUNNING_ON_HCPU2;
724	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
725	
726	            temp_sec_config->running_imgs[CORE_HCPU] = &(flash_config->imgs[hcpu2_img_idx]);
727	            update_sec_flash(temp_sec_config);
728	            break;
729	        }
730	        case DFU_DES_NONE:
731	        {
732	            // first power on, use current
733	            hcpu_des = DFU_DES_RUNNING_ON_HCPU2;
734	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
735	            break;
736	        }
737	        default:
738	            hcpu_des = DFU_DES_RUNNING_ON_HCPU2;
739	            HAL_Set_backup(RTC_BACKUP_NAND_OTA_DES, hcpu_des);
740	        }
741	    }
742	}
