981	            dfu_boot_img_in_flash(flash_id);
982	        }
983	
984	        /* load extended img if present, such as ACPU img */
985	        if (g_sec_config->imgs[DFU_FLASH_IMG_IDX(DFU_FLASH_HCPU_EXT2)].length != FLASH_UNINIT_32)
986	        {
987	            dfu_boot_img_in_flash(DFU_FLASH_HCPU_EXT2);
988	        }
989	
990	        if (g_sec_config->running_imgs[CORE_HCPU] != (struct image_header_enc *)FLASH_UNINIT_32)
991	        {
992	            int flash_id = ((uint32_t)sec_config_cache.running_imgs[CORE_HCPU] - FLASH_BASE_ADDR - 0x1000) / sizeof(struct image_header_enc) + DFU_FLASH_IMG_LCPU;
993	            dfu_boot_img_in_flash(flash_id);
994	        }
995	
996	        boot_image(CORE_HCPU, 0);
997	    }
