 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/* SF32LB58 nxboot bootloader memory layout:
 *
 *   Matches SiFli-SDK boot_loader for sf32lb58x_v2:
 *     - ROM bootrom loads bootloader from MPI5 flash (0x1C020000) into SRAM
 *     - Bootloader executes entirely from SRAM (0x20000000)
 *     - Bootloader initializes PSRAM, loads app from NAND to PSRAM, jumps
 *
 *   Flash (load):  MPI5 0x1C020000, 128 KB (bootloader storage)
 *   SRAM (exec):   0x20000000, 64 KB code + 64 KB data
 *   Retention RAM: 0x00020000, 64 KB (sleep-critical data)
 *   PSRAM:         MPI1 0x60000000, 32 MB (app code + data after boot)
 *
 *   The ROM bootrom copies the entire image from flash to SRAM before
 *   jumping to the entry point, so NO startup copy is needed — .data and
 *   .bss are already in SRAM.
 */

MEMORY
{
  flash (rx)         : ORIGIN = 0x1C020000, LENGTH = 128K  /* MPI5 bootloader storage */
  sram (rwx)         : ORIGIN = 0x20000000, LENGTH = 64K   /* Code execution from SRAM */
  sram_data (rwx)    : ORIGIN = 0x20010000, LENGTH = 64K   /* Data/BSS in SRAM */
  retention_ram (rw) : ORIGIN = 0x00020000, LENGTH = 64K
  psram (rwx)        : ORIGIN = 0x60000000, LENGTH = 32M   /* MPI1 PSRAM for app */
}

OUTPUT_ARCH(arm)
EXTERN(_vectors)
/* Provide __Vectors alias for SystemInit() compatibility */
__Vectors = _vectors;
ENTRY(_stext)

SECTIONS
{
    /* Discard build-id to ensure vectors start at SRAM base */
    /DISCARD/ : {
        *(.note.gnu.build-id)
    }

    /* .text and vectors go into SRAM for execution.
     * AT > flash means the LMA (load address) is in flash at 0x1C020000,
     * but the ROM bootrom handles the copy — startup code does NOT copy. */

    .text : {
        _stext = ABSOLUTE(.);
        . = ALIGN(512);
        KEEP(*(.vectors))
        . = ALIGN(4);
        *(.text .text.*)
        *(.fixup)
        *(.gnu.warning)
        *(.rodata .rodata.*)
        *(.gnu.linkonce.t.*)
        *(.glue_7)
        *(.glue_7t)
        *(.got)
        *(.gcc_except_table)
        *(.gnu.linkonce.r.*)

        KEEP(*(.init))
        KEEP(*(.fini))

        /* Section information for finsh shell */
        . = ALIGN(4);
        __fsymtab_start = .;
        KEEP(*(FSymTab))
        __fsymtab_end = .;

        . = ALIGN(4);
        __vsymtab_start = .;
        KEEP(*(VSymTab))
        __vsymtab_end = .;

        . = ALIGN(4);
        __rt_utest_tc_tab_start = .;
        KEEP(*(UtestTcTab))
        __rt_utest_tc_tab_end = .;

        /* Section information for initial */
        . = ALIGN(4);
        __rt_init_start = .;
        KEEP(*(SORT(.rti_fn*)))
        __rt_init_end = .;

        . = ALIGN(4);
        __sifli_reg_start__ = .;
        KEEP(*(SORT(.sifli_reg*)))
        __sifli_reg_end__ = .;

        . = ALIGN(4);
        __bt_sifli_reg_start__ = .;
        KEEP(*(SORT(.bt_sifli_reg*)))
        __bt_sifli_reg_end__ = .;

        /* Section information for modules */
        . = ALIGN(4);
        __rtmsymtab_start = .;
        KEEP(*(RTMSymTab))
        __rtmsymtab_end = .;

        /* Section information for LCD drivers */
        . = ALIGN(4);
        LcdDriverDescTab_start = .;
        KEEP(*(LcdDriverDescTab))
        LcdDriverDescTab_end = .;

        . = ALIGN(4);
        __usbh_class_info_start__ = .;
        KEEP(*(.usbh_class_info))
        __usbh_class_info_end__ = .;

        . = ALIGN(4);
        __nand_cfg_db_start__ = .;
        KEEP(*(.nand_cfg_db))
        __nand_cfg_db_end__ = .;

        KEEP(*(.eh_frame*))
        _etext = ABSOLUTE(.);
    } > sram AT > flash

    .ARM.extab : {
        *(.ARM.extab* .gnu.linkonce.armextab.*)
    } > sram AT > flash

    __exidx_start = ABSOLUTE(.);
    .ARM.exidx : {
        *(.ARM.exidx* .gnu.linkonce.armexidx.*)
    } > sram AT > flash
    __exidx_end = ABSOLUTE(.);

    /* .data and .bss in SRAM — ROM bootrom already copied them from flash */
    .data : {
        _sdata = ABSOLUTE(.);
        __data_start__ = .;
        *(vtable)
        *(.data)
        *(.data.*)
        *(.gnu.linkonce.d.*)
        *(.l1_ret_data_*)
        CONSTRUCTORS

        . = ALIGN(4);
        /* preinit data */
        PROVIDE_HIDDEN (__preinit_array_start = .);
        KEEP(*(.preinit_array))
        PROVIDE_HIDDEN (__preinit_array_end = .);

        . = ALIGN(4);
        /* init data */
        _sinit = ABSOLUTE(.);
        PROVIDE(__ctors_start__ = .);
        PROVIDE_HIDDEN (__init_array_start = .);
        KEEP(*(SORT(.ctors.*)))
        KEEP(*(.ctors))
        KEEP(*(SORT(.init_array.*)))
        KEEP(*(.init_array))
        _einit = ABSOLUTE(.);
        PROVIDE_HIDDEN (__init_array_end = .);
        PROVIDE(__ctors_end__ = .);

        . = ALIGN(4);
        /* fini data */
        PROVIDE(__dtors_start__ = .);
        PROVIDE_HIDDEN (__fini_array_start = .);
        KEEP(*(SORT(.dtors.*)))
        KEEP(*(.dtors))
        KEEP(*(SORT(.fini_array.*)))
        KEEP(*(.fini_array))
        PROVIDE_HIDDEN (__fini_array_end = .);
        PROVIDE(__dtors_end__ = .);

        KEEP(*(.jcr*))
        . = ALIGN(4);
        __data_end__ = .;
        _edata = ABSOLUTE(.);
    } > sram_data

    .ramfunc : {
        . = ALIGN(4);
        _sramfunc = ABSOLUTE(.);
        *(.ramfunc .ramfunc.*)
        . = ALIGN(4);
        _eramfunc = ABSOLUTE(.);
    } > sram_data

    _siramfunc = LOADADDR(.ramfunc);

    .bss : {
        . = ALIGN(4);
        _sbss = ABSOLUTE(.);
        __bss_start__ = .;
        *(.bss)
        *(.bss.*)
        *(.gnu.linkonce.b.*)
        *(COMMON)
        . = ALIGN(4);
        __bss_end__ = .;
        _ebss = ABSOLUTE(.);
    } > sram_data

    /* Retention RAM for sleep-critical data */
